const now=new Date().toISOString();
return [{json:{
  generated_at:now,
  campaign_id:'daily-content-acquisition-2026',
  prompt:'Crie dois rascunhos originais de aquisição para a Filtra.AI, em português brasileiro. Retorne SOMENTE JSON válido com as chaves devto_title, devto_body, buffer_post. O artigo para DEV.to deve ter 700-1100 palavras, ser útil e prático sobre gestão de reputação online, avaliações de clientes, SEO local ou fluxos de reputação assistidos por IA. Não use spam, não invente estatísticas, clientes, depoimentos, preços, parcerias ou resultados. Inclua no final uma chamada discreta para conhecer a auditoria gratuita da Filtra.AI com este link exato: https://filtraai.com/auditoria-gratuita?utm_source=content&utm_medium=organic&utm_campaign=daily-content&utm_content=devto-daily . O post para Buffer deve ter menos de 700 caracteres, ser útil e natural, em português brasileiro, terminar com CTA curto e incluir este link exato: https://filtraai.com/auditoria-gratuita?utm_source=content&utm_medium=organic&utm_campaign=daily-content&utm_content=buffer-daily . Evite promessas de crescimento garantido. Mantenha a revisão humana: ambos são rascunhos, nunca publique automaticamente.'
}}];

const source=$json||{};
let parsed=null;
try {
  const raw=source.choices?.[0]?.message?.content;
  if(raw) {
    const cleaned=String(raw).replace(/^\s*```json\s*/i,'').replace(/\s*```\s*$/,'').trim();
    parsed=JSON.parse(cleaned);
  }
} catch {}
if(!parsed || !parsed.devto_title || !parsed.devto_body || !parsed.buffer_post) {
  parsed={
    devto_title:'Como transformar avaliações de clientes em ações práticas de reputação',
    devto_body:'Avaliações de clientes são mais do que uma nota pública. Elas mostram expectativas, pontos fortes, falhas de atendimento e temas que se repetem na experiência. Uma rotina de reputação começa por reunir avaliações reais, identificar padrões, priorizar problemas e acompanhar se as ações tomadas reduzem as reclamações recorrentes.\n\nA inteligência artificial pode ajudar a resumir grandes volumes de feedback, agrupar assuntos semelhantes e preparar rascunhos de respostas. Ainda assim, o contexto e a revisão humana continuam importantes: automação deve reduzir trabalho repetitivo, não inventar avaliações nem publicar respostas genéricas sem conferência.\n\nUma rotina útil conecta os sinais à operação. Se um problema de prazo aparece repetidamente, por exemplo, a equipe responsável precisa receber essa informação, definir uma ação e verificar se o tema continua aparecendo nas avaliações seguintes. Assim, reputação deixa de ser apenas um painel e passa a apoiar melhorias concretas.\n\nA Filtra.AI ajuda empresas a organizar avaliações e feedback para identificar temas recorrentes e transformar sinais em prioridades de melhoria. Faça uma auditoria gratuita com avaliações reais da sua empresa: https://filtraai.com/auditoria-gratuita?utm_source=content&utm_medium=organic&utm_campaign=daily-content&utm_content=devto-daily',
    buffer_post:'Avaliações não são só uma nota: revelam padrões da experiência do cliente. Organize feedback, identifique temas recorrentes e transforme sinais em ações práticas — sem inventar dados e mantendo revisão humana. Faça uma auditoria gratuita: https://filtraai.com/auditoria-gratuita?utm_source=content&utm_medium=organic&utm_campaign=daily-content&utm_content=buffer-daily'
  };
}
return [{json:{campaign_id:'daily-content-acquisition-2026',generated_at:new Date().toISOString(),...parsed}}];
